"""Reveal the full revision tool from a settled, non-writing preparation receipt."""

from __future__ import annotations

from typing import TYPE_CHECKING, Any

from codey.runtime.core.models import ToolCall, ToolResult

if TYPE_CHECKING:
    from codey.toolchain.tool_spec import ToolSpec

PREPARE = "prepare_knowledge_revision"
REVISION_GUIDANCE = (
    "Use knowledge_commit to edit existing stored objects with exact database references; "
    "current eN labels belong in the submission batch, not knowledge_commit. "
)
PREPARE_GUIDANCE = (
    "For authorized changes to stored objects, first call prepare_knowledge_revision to reveal knowledge_commit; "
    "preparation writes nothing. Current eN labels belong in the submission batch, not knowledge_commit. "
)
PREPARE_DESCRIPTION = (
    "Make the full knowledge_commit tool available next turn for authorized stored-knowledge changes. "
    "This only prepares the tool; it does not create, edit or verify knowledge. "
    "Ordinary lookup needs no preparation; new answer knowledge can use submit_research_answer.knowledge_updates."
)


def _denied(session: Any) -> set[str]:
    return {str(name or "").strip().lower() for name in (getattr(session, "controller_denied", ()) or ())}


def revision_ready(session: Any) -> bool:
    # Preserve the original recovery context after a failed read. Only settled
    # receipts count, so restart follows the same route without a mutable flag.
    return any((not result.ok and result.call.name == "knowledge_read")
               or (result.ok and result.call.name == PREPARE
                   and result.canonical.get("knowledge_revision_ready") is True)
               for result in getattr(session, "_memory_results", {}).values())


def preparation_spec() -> ToolSpec:
    from codey.toolchain.tool_spec import ToolSpec

    return ToolSpec(
        name=PREPARE, grant="knowledge.write", executor="knowledge", replay_class="safe",
        description=PREPARE_DESCRIPTION,
        json_examples=('{"tool":"prepare_knowledge_revision","args":{}}',),
    )


def revision_tool_names(session: Any, names: tuple[str, ...] | None) -> tuple[str, ...] | None:
    from codey.research.answer_contract import whole_research

    if (not whole_research(session) or names is None or "knowledge_commit" not in names
            or getattr(session, "model_tool_names", None) is not None or revision_ready(session)
            or PREPARE in _denied(session)):
        return names
    return tuple(PREPARE if name == "knowledge_commit" else name for name in names)


def revision_guidance(session: Any, guidance: str) -> str:
    from codey.research.answer_contract import whole_research

    if (whole_research(session) and getattr(session, "model_tool_names", None) is None
            and not revision_ready(session) and session.policy.allows("knowledge.write")
            and not {PREPARE, "knowledge_commit"}.intersection(_denied(session))):
        return guidance.replace(REVISION_GUIDANCE, PREPARE_GUIDANCE)
    return guidance


def preparation_result(session: Any, scope: object, call: ToolCall) -> ToolResult:
    from codey.research.answer_contract import AnswerScope, digest, whole_research

    if (not whole_research(session) or not isinstance(scope, AnswerScope)
            or scope.task_digest != digest(session.task_text) or call.args
            or not session.policy.allows("knowledge.write")
            or {PREPARE, "knowledge_commit"}.intersection(_denied(session))):
        return ToolResult(call, "ERROR: knowledge revision preparation is not authorized for this task.", ok=False)
    return ToolResult(call, "Revision tool prepared; knowledge_commit is available next turn. "
                      "No knowledge was created or changed. Read the target before revising it; "
                      "keep exact ids, expected revisions, scope and references.", ok=True,
                      canonical={"knowledge_revision_ready": True})

source_snapshot.codey/operations/kernel_protocol.py:
"""Single turn protocol for the unified kernel: JSON text and native calls.

Web JSON replies and native ``AssistantTurn`` values converge here into one
canonical ``ToolPlan`` under the same ``TaskPolicy`` and controller state.
Unknown tools are denied, never passed as ``control``.
"""

from __future__ import annotations

import json
from collections.abc import Mapping
from dataclasses import dataclass, replace
from typing import TYPE_CHECKING, Any

from codey.protocols.text_turn import DecodedTextTurn, TextAnswer, TextError, TextRequests, decode_text_turn
from codey.providers.base import AssistantTurn, TurnFinish
from codey.runtime.core.models import Control, ToolCall, ToolPlan
from codey.toolchain.tool_spec import _CONTROLLER_ALIAS_ID_ARG as _ALIAS_ARGS
from codey.toolchain.tool_spec import is_text_batch_tool

MAX_NATIVE_CALLS_PER_TURN = 8

if TYPE_CHECKING:
    from codey.operations.task_session import TaskSession
    from codey.research.answer_contract import AnswerScope
    from codey.research.local_scope import ResearchScope


@dataclass(frozen=True)
class TurnSnapshot:
    """One authoritative per-round observation: policy ∩ current facts.

    Built once at round start; any build failure raises and the kernel
    terminates the turn as controller_failure (fail-closed), never a stale
    fallback list. Carries the allowed tools, frozen tool definitions plus
    both protocols' contracts for the round. The snapshot object贯穿发送、
    解析与执行：注册表变化下一轮生效，本轮解析与执行共用同一冻结定义。
    ``frozen_specs`` are nested-immutable (mapping proxies inside); the
    ``custom_executors`` table freezes third-task bindings so a mid-turn
    registry swap cannot reroute this turn's execution.
    """

    allowed: tuple[str, ...] | None
    contract_text: str
    tool_names: tuple[str, ...] = ()
    policy: Any = None
    frozen_specs: tuple[Any, ...] = ()
    custom_executors: tuple[tuple[str, Any], ...] = ()
    implementation_compatible: bool = True
    nested_tool_names: tuple[str, ...] = ()
    research_scope: ResearchScope | AnswerScope | None = None

    @property
    def inventory_names(self) -> tuple[str, ...]:
        return tuple(dict.fromkeys((*self.tool_names, *self.nested_tool_names)))

    @property
    def model_specs(self) -> tuple[Any, ...]:
        return tuple(spec for spec in self.frozen_specs if spec.name in self.tool_names)


@dataclass(frozen=True)
class ReceivedProviderTurn:
    """A received response with its original request's declarations and turn."""

    reply: AssistantTurn | str
    snapshot: TurnSnapshot
    prompt: str
    owner_session: TaskSession
    logical_turn: int = 1
    window_ref: Any = None
    effect_scope: str = ""


def controller_allowed_for_session(session: Any) -> tuple[str, ...] | None:
    if getattr(session, "task_kind", "") == "research_review":
        raise ValueError("same-model research assessment execution has been retired")
    policy = getattr(session, "policy", None)
    try:
        denied = {"submit_research_review", "prepare_knowledge_revision"} | {str(n or "").strip().lower() for n in (getattr(session, "controller_denied", ()) or ())
                  if str(n or "").strip()}
    except Exception:
        denied = {"submit_research_review", "prepare_knowledge_revision"}
    if not bool(getattr(policy, "strict_research", False)):
        denied.add("submit_research_answer")
        base: tuple[str, ...] | None = None
    else:
        from codey.research.answer_contract import ANSWER_TOOLS, whole_research

        if whole_research(session):
            from codey.research.revision_tools import revision_tool_names

            names = tuple(name for name in ANSWER_TOOLS if name not in denied and (
                name not in {"open_result", "reopen_source", "open_hit"} or getattr(session,
                {"open_result": "search_results", "reopen_source": "source_ids", "open_hit": "hit_targets"}[name], None)))
            return revision_tool_names(session, names)
        # Research exposes one simple acquisition write, keeping complex
        # knowledge revision tools available to ordinary/hybrid tasks.
        denied.update({"knowledge_write", "knowledge_commit", "knowledge_link"})
        results = dict(getattr(session, "search_results", {}) or {})
        opened = set(getattr(session, "opened_sources", set()) or set())
        evidence = list(getattr(session, "evidence", []) or [])
        if not getattr(session, "research_questions", ()):
            base = ("research_plan", "done")
        elif not results and not opened:
            base = ("knowledge_search", "knowledge_read", "web_search", "open_url", "save_inference", "done")
        elif not opened:
            base = ("knowledge_search", "knowledge_read", "web_search", "open_url", "open_result", "save_inference", "done")
        elif not evidence:
            base = (
                "knowledge_search",
                "knowledge_read",
                "web_search",
                "open_url",
                "open_result",
                "reopen_source",
                "open_hit",
                "source_search",
                "save_finding",
                "save_inference",
                "knowledge_write",
                "done",
            )
        else:
            base = None
        if base is not None and "research_plan" not in base:
            base = ("research_plan", *base)
        from codey.research.local_scope import registered_plan

        if getattr(session, "task_kind", "") == "research" and registered_plan(session) is not None:
            base = ("knowledge_search", "knowledge_read", "web_search", "open_url", "open_result", "reopen_source",
                    "open_hit", "source_search", "save_finding", "save_inference", "submit_research_answer")
        else:
            denied.add("submit_research_answer")
    if base is not None:
        base = (*base, "ask_user", "read_tool_result")
    # Reference aliases require an observed target, in ordinary and strict
    # tasks alike. The resulting list drives both wire protocols and execution.
    for alias, facts in (("open_result", "search_results"),
                         ("reopen_source", "source_ids"), ("open_hit", "hit_targets")):
        if not getattr(session, facts, None):
            denied.add(alias)
    if not denied:
        return base
    if base is None:
        # 否决表存在时 unlimited 即不可用：按策略可见全集减去否决，
        # 收窄仍经同一快照进入提示、schema、解析与执行。
        from codey.toolchain.tool_spec import visible_tool_names_for_snapshot

        base = tuple(visible_tool_names_for_snapshot(policy, None))
    return tuple(name for name in base if name not in denied)


def _frozen_specs_for_names(names: tuple[str, ...]) -> tuple[Any, ...]:
    """Capture immutable definitions for exactly the advertised names."""
    import copy as _copy

    try:
        from codey.toolchain.tool_spec import freeze_spec_parameters as _freeze
        from codey.toolchain.tool_spec import tool_specs as _all_specs
    except Exception as exc:
        raise RuntimeError(f"tool snapshot unavailable: {exc}") from exc
    specs = _all_specs()
    frozen: list[Any] = []
    for name in names:
        spec = specs.get(name)
        if spec is None:
            continue
        try:
            copied = _copy.deepcopy(spec)
        except Exception as exc:
            raise RuntimeError(f"tool snapshot freeze failed for {name}: {exc}") from exc
        try:
            frozen.append(_freeze(copied))
        except Exception as exc:
            raise RuntimeError(f"tool snapshot freeze failed for {name}: {exc}") from exc
    return tuple(frozen)


def _frozen_custom_executors(names: tuple[str, ...]) -> tuple[tuple[str, Any], ...]:
    """Freeze third-task executor bindings for this turn (same source)."""
    try:
        from codey.toolchain.tool_spec import custom_executor_for as _fn_for
    except Exception as exc:
        raise RuntimeError(f"tool snapshot executors unavailable: {exc}") from exc
    bindings: list[tuple[str, Any]] = []
    for name in names:
        try:
            fn = _fn_for(name)
        except Exception as exc:
            raise RuntimeError(f"tool snapshot executor freeze failed for {name}: {exc}") from exc
        bindings.append((name, fn))
    return tuple(bindings)


def frozen_spec_map(snapshot: TurnSnapshot | None) -> dict[str, Any] | None:
    if snapshot is None:
        return None
    mapping = {spec.name: spec for spec in snapshot.frozen_specs}
    if set(mapping) != set(snapshot.inventory_names):
        raise ValueError("incomplete tool snapshot definitions")
    return mapping


def frozen_custom_executor_map(snapshot: TurnSnapshot | None) -> dict[str, Any] | None:
    if snapshot is None:
        return None
    mapping = dict(snapshot.custom_executors)
    if set(mapping) != set(snapshot.inventory_names):
        raise ValueError("incomplete tool snapshot executor bindings")
    return mapping


def build_turn_snapshot(session: Any, *, native: bool = False, research_repair: Any = None) -> TurnSnapshot:
    """Build the round's authoritative snapshot; raises on failure."""
    # Fail closed: a snapshot computation failure never encodes as None
    # (unlimited). Callers must treat the exception as a per-turn config
    # error and stop.
    from codey.research.answer_contract import AnswerScope, answer_spec, whole_research

    whole = whole_research(session)
    allowed = controller_allowed_for_session(session)
    if not whole and session.policy.strict_research and session.task_kind == "research" and not session.research_questions:
        allowed = tuple(name for name in (allowed or ()) if name != "done")
    from codey.research.local_scope import ResearchScope, current_scope, registered_plan

    scope = current_scope(session, repair=research_repair) if session.policy.strict_research and session.task_kind == "research" else None
    if not whole and registered_plan(session) is not None and session.policy.strict_research and session.task_kind == "research":
        domain_tools = {"knowledge_search", "knowledge_read", "web_search", "open_url", "open_result", "reopen_source",
                        "open_hit", "source_search", "save_finding", "save_inference", "submit_research_answer",
                        "read_tool_result", "ask_user"} if scope else set()
        if scope is not None and not scope.passage_refs:
            domain_tools.discard("save_finding")
        if scope is not None and scope.submission_mode == "inline":
            domain_tools.discard("save_finding")
        if isinstance(scope, ResearchScope) and not scope.finding_refs:
            domain_tools.discard("save_inference")
        allowed = tuple(name for name in (allowed or ()) if name in domain_tools)
    from codey.toolchain.tool_spec import visible_tool_names_for_snapshot

    authorized = tuple(visible_tool_names_for_snapshot(session.policy, allowed, native=native))
    if (scope is not None
            or session.policy.strict_research and session.task_kind == "research" and not session.research_questions):
        authorized = tuple(name for name in authorized if name in (allowed or ()))
    exposure = getattr(session, "model_tool_names", None)
    if exposure is not None and (len(set(exposure)) != len(exposure) or not set(exposure) <= set(authorized)):
        raise ValueError("model exposure must narrow the authorized tool inventory")
    names = tuple(name for name in authorized if exposure is None or name in exposure)
    frozen = _frozen_specs_for_names(authorized)
    if not whole and session.policy.strict_research and session.task_kind == "research" and not session.research_questions:
        from codey.research.plan_contract import compact_plan_spec

        frozen = tuple(compact_plan_spec(spec, session.task_text) if spec.name == "research_plan" else spec for spec in frozen)
    from codey.research.tool_contract import done_spec_for_purpose, question_bound_spec

    purpose = ("evidence" if getattr(session, "task_kind", "") == "evidence_followup" else
               "report" if session.policy.strict_research else "ordinary")
    frozen = tuple(done_spec_for_purpose(spec, purpose, task=session.task_text,
                                        questions=session.research_questions) if spec.name == "done" else spec
                   for spec in frozen)
    from codey.research.questions import requires_question_ref

    if requires_question_ref(session):
        frozen = tuple(question_bound_spec(spec, required=True) for spec in frozen)
    if isinstance(scope, AnswerScope):
        frozen = tuple(answer_spec(spec, scope) for spec in frozen)
    elif scope is not None:
        from codey.research.local_scope import scoped_spec

        frozen = tuple(scoped_spec(spec, scope) for spec in frozen)
    nested: tuple[str, ...] = ()
    if "codemode" in names:
        from codey.codemode.catalog import build_codemode_catalog, render_declarations

        catalog = build_codemode_catalog(frozen, allow_writes=session.policy.allows("project.write"))
        nested = tuple(entry.name for entry in catalog.entries)
        declarations = render_declarations(catalog)
        frozen = tuple(replace(spec, declarations=declarations)
                       if spec.name == "codemode" else spec for spec in frozen)
    from codey.toolchain.tool_spec import json_contract_text as _contract

    # JSON 与 native 契约同源：都从同一冻结定义生成，不再查实时注册表。
    inventory = tuple(dict.fromkeys((*names, *nested)))
    by_name = {spec.name: spec for spec in frozen}
    frozen = tuple(by_name[name] for name in inventory)
    contract_now = _contract(tuple(by_name[name] for name in names))
    executors = _frozen_custom_executors(inventory)
    return TurnSnapshot(
        allowed=allowed,
        contract_text=contract_now,
        tool_names=names,
        policy=session.policy,
        frozen_specs=frozen,
        custom_executors=executors,
        nested_tool_names=nested,
        research_scope=scope,
    )


_CONTROLLER_ALIASES = frozenset(_ALIAS_ARGS or {})


def _grant_for_tool(tool: str) -> str:
    try:
        from codey.toolchain.tool_spec import spec_for_tool
    except Exception:
        return ""
    try:
        spec = spec_for_tool(tool)
    except Exception:
        return ""
    if spec is None or not spec.grant:
        # Unknown tools are denied, never passed as control.
        return ""
    return spec.grant


def _canonical_name(tool: str) -> str:
    try:
        from codey.toolchain.tool_spec import canonical_tool_name
    except Exception:
        return (tool or "").strip().lower()
    try:
        return canonical_tool_name(tool)
    except Exception:
        return (tool or "").strip().lower()


def _is_coding_only_tool(tool: str) -> bool:
    name = _canonical_name(tool)
    if not name or name == "done":
        return False
    try:
        from codey.toolchain.tool_spec import spec_for_tool
    except Exception:
        return False
    try:
        spec = spec_for_tool(name)
    except Exception:
        return False
    return spec is not None and spec.executor == "project"


def _controller_allows(tool: str, allowed: set[str] | None) -> bool:
    if allowed is None:
        return True
    name = (tool or "").strip().lower()
    if _is_coding_only_tool(name):
        return True
    if name == "open_url":
        return bool({"open_url", *_CONTROLLER_ALIASES} & allowed)
    return name in allowed


def _policy_allows(policy: Any, tool: str, frozen_specs: dict[str, Any] | None = None) -> bool:
    allows = getattr(policy, "allows", None)
    if not callable(allows):
        return False
    try:
        spec = frozen_specs.get(tool) if frozen_specs is not None else None
        grant = spec.grant if spec is not None else "" if frozen_specs is not None else _grant_for_tool(tool)
        return bool(grant and allows(grant))
    except Exception:
        return False


def _disallowed_plan(tool: str, *, controller: bool = False) -> ToolPlan:
    if controller:
        message = f"{tool} is not allowed by the current controller state"
        kind = "disallowed_tool"
    else:
        message = f"disallowed tool for this task policy: {tool}"
        kind = "disallowed_tool"
    return ToolPlan(calls=[], control=None, protocol_error=message, protocol_error_kind=kind,
                    protocol_tool_name=(tool or ""))


def _invalid_plan(message: str, *, tool: str = "", kind: str = "invalid_args") -> ToolPlan:
    return ToolPlan(calls=[], control=None, protocol_error=message, protocol_error_kind=kind,
                    protocol_tool_name=(tool or ""))


def _tool_and_args(obj: Mapping[str, Any]) -> tuple[str, dict[str, Any]]:
    tool = str(obj.get("tool", "") or "").strip().lower()
    raw_args = obj.get("args", None)
    if isinstance(raw_args, dict):
        args = dict(raw_args)
    elif raw_args is None:
        args = {k: v for k, v in obj.items() if k != "tool"}
    else:
        args = dict[str, object]()
    return tool, args


def _validate_coding_args(tool: str, args: dict[str, Any]) -> tuple[dict[str, Any], str]:
    if (tool or "").strip().lower() == "edit" and isinstance(args, dict):
        # Top-level old/new fields are not part of the canonical edit shape.
        if "old_string" in args or "new_string" in args:
            return {}, "edit requires replacements for existing files"
        replacements = args.get("replacements")
        if isinstance(replacements, list):
            for item in replacements:
                if isinstance(item, dict) and ("search" in item or "replace" in item):
                    return {}, "edit rejects legacy replacement fields: use old_string/new_string"
        for legacy_top in ("search", "replace"):
            if legacy_top in args:
                return {}, f"edit rejects legacy alias: {legacy_top}"
    try:
        from codey.toolchain import definition as tool_defs
        from codey.toolchain.runtime import MAX_REPLACEMENTS, READ_MAX_LINES
        from codey.toolchain.tool_args_repair import (
            ToolArgLimits,
            ToolArgsRepairError,
            normalize_tool_args,
        )
    except Exception as exc:
        return {}, f"coding validator unavailable: {exc}"
    spec = tool_defs.TOOL_DEFINITION_BY_NAME.get(tool)
    if spec is None or spec.runtime_name is None:
        return {}, f"unknown tool: {tool}"
    try:
        repair = normalize_tool_args(
            spec.runtime_name, dict(args),
            limits=ToolArgLimits(max_replacements=MAX_REPLACEMENTS, read_max_lines=READ_MAX_LINES),
        )
    except ToolArgsRepairError as exc:
        return {}, str(exc)
    except Exception as exc:
        return {}, f"{tool} args invalid: {exc}"
    return dict(repair.args), ""


def _validate_research_args(tool: str, args: dict[str, Any]) -> tuple[dict[str, Any], str]:
    if tool in _CONTROLLER_ALIASES:
        id_key = {"open_result": "result_id", "reopen_source": "source_id", "open_hit": "hit_id"}[tool]
        value = str(args.get(id_key, "") or "").strip()
        if not value:
            return {}, f"{tool} missing required arg '{id_key}'"
        return {**args, id_key: value}, ""
    if tool == "source_search" and "source_id" in args:
        # Controller alias form: source_id resolves via controller state at
        # execution time; here only require a non-empty id and query.
        sid = str(args.get("source_id", "") or "").strip()
        query = str(args.get("query", "") or "").strip()
        if not sid:
            return {}, "source_search missing required arg 'source_id'"
        if not query:
            return {}, "source_search missing required arg 'query'"
        return {**args, "source_id": sid, "query": query}, ""
    try:
        from codey.research.tool_contract import validate_tool_args
    except Exception as exc:
        return {}, f"research validator unavailable: {exc}"
    try:
        result = validate_tool_args(tool, dict(args))
    except Exception as exc:
        return {}, f"{tool} args invalid: {exc}"
    if not result.ok:
        return {}, result.error or f"{tool} args invalid"
    # The contract validator fills optional defaults for older callers. The
    # shared kernel retains only arguments the model actually supplied, so
    # restricted subflows can still reject explicitly forbidden fields.
    return {key: value for key, value in result.args.items() if key in args}, ""


def _lookup_spec(name: str, frozen_specs: dict[str, Any] | None) -> tuple[Any, str]:
    try:
        if frozen_specs is not None:
            spec = frozen_specs.get(name)
            return spec, (spec.executor if spec is not None else "")
        from codey.toolchain.tool_spec import spec_for_tool as _spec_for

        spec = _spec_for(name)
        return spec, (spec.executor if spec is not None else "")
    except Exception:
        return None, ""


def _spec_error_for(name: str, args: dict[str, Any], spec: Any, frozen_specs: dict[str, Any] | None) -> str:
    payload = args if isinstance(args, dict) else dict[str, object]()
    try:
        if frozen_specs is not None:
            from codey.toolchain.tool_spec import validate_args_with_spec as _frozen_validate

            return _frozen_validate(spec, payload) or ""
        from codey.toolchain.tool_spec import validate_args_against_spec as _live_validate

        return _live_validate(name, payload) or ""
    except Exception as exc:
        detail = str(exc).strip()[:200] or type(exc).__name__
        return f"{name} args invalid: spec validator failed ({detail})"


def _validate_tool_args(
    tool: str, args: dict[str, Any], *, frozen_specs: dict[str, Any] | None = None,
) -> tuple[dict[str, Any], str]:
    name = _canonical_name(tool) or (tool or "").strip().lower()
    # ToolSpec is the single authoritative definition: required-arg presence
    # is decided here so JSON/native schemas and validation cannot drift.
    # Project/research legacy validators are additional type-repair constraints
    # only; third-task (custom) tools pass on the generic spec alone.
    spec, executor = _lookup_spec(name, frozen_specs)
    if spec is None:
        return {}, f"unknown tool: {tool or '?'}"
    spec_error = _spec_error_for(name, args if isinstance(args, dict) else {}, spec, frozen_specs)
    if spec_error:
        return {}, spec_error
    if name == "ask_user":
        from codey.task.questions import question_args
        try:
            return question_args(args), ""
        except ValueError as exc:
            return {}, str(exc)
    if name == "done":
        # ``done`` is a control tool with no runtime executor. Its
        # canonical ToolSpec validation above is the complete contract.
        return dict(args), ""
    if name == "codemode":
        try:
            from codey.codemode.protocol import parse_codemode_args

            program = parse_codemode_args(args if isinstance(args, dict) else {})
            from codey.runtime.core.models import canonical_json_mapping

            return {"code": program.code, "language": program.language,
                    "inputs": canonical_json_mapping(program.inputs)}, ""
        except ValueError as exc:
            return {}, str(exc)
    # Custom/third-task tools: generic spec validation is sufficient.
    # They run via injected executors; no legacy coding/research repair.
    if executor not in {"project", "source", "knowledge"}:
        # Controller aliases always lower via research validation.
        is_alias = name in set(_ALIAS_ARGS or {})
        if is_alias or (name == "source_search" and isinstance(args, dict) and "source_id" in args):
            return _validate_research_args(name, args if isinstance(args, dict) else {})
        return dict(args) if isinstance(args, dict) else {}, ""
    if name in _CONTROLLER_ALIASES or (isinstance(args, dict) and name == "source_search" and "source_id" in args):
        return _validate_research_args(name, args)
    if executor == "project":
        return _validate_coding_args(name, args)
    if executor in {"source", "knowledge"}:
        return dict(args), ""
    return {}, "unsupported tool executor"


def _expand_text_batch(tool: str, args: dict[str, Any]) -> tuple[list[tuple[str, dict[str, Any], str]], str]:
    """Lower bounded read-only wrappers; validate the whole batch before effects."""
    from codey.toolchain.definition import MAX_PARALLEL_CALLS, TOOL_DEFINITION_BY_NAME

    if tool == "read_files":
        paths = args.get("paths")
        if isinstance(paths, str):
            paths = [paths]
        if not isinstance(paths, list) or not paths or len(paths) > MAX_NATIVE_CALLS_PER_TURN:
            return [], f"read_files requires 1..{MAX_NATIVE_CALLS_PER_TURN} paths"
        if any(not isinstance(path, str) or not path.strip() for path in paths):
            return [], "read_files paths must be non-empty strings"
        return [("read_file", {"path": path}, "") for path in paths], ""
    calls = args.get("calls")
    if not isinstance(calls, list) or not calls or len(calls) > MAX_PARALLEL_CALLS:
        return [], f"parallel requires 1..{MAX_PARALLEL_CALLS} read-only calls"
    expanded = []
    for row in calls:
        if not isinstance(row, dict):
            return [], "every parallel call must be an object"
        name, child_args = _tool_and_args(row)
        definition = TOOL_DEFINITION_BY_NAME.get(name)
        if definition is None or not definition.parallel_safe:
            return [], "parallel accepts only list_dir, read_file, and grep"
        if "args" in row and not isinstance(row["args"], dict):
            return [], f"{name} args must be an object"
        expanded.append((name, child_args, ""))
    return expanded, ""


def _lower_text_batches(items: list[tuple[str, dict[str, Any], str]]) -> tuple[list[tuple[str, dict[str, Any], str]], str]:
    expanded = []
    for raw_tool, args, call_id in items:
        name = _canonical_name(raw_tool)
        if is_text_batch_tool(name):
            if call_id:
                return [], "batch wrappers are text-only; native calls require individual ids"
            from codey.toolchain.tool_spec import validate_args_against_spec

            error = validate_args_against_spec(name, args)
            if error:
                return [], error
            children, error = _expand_text_batch(name, args)
            if error:
                return [], error
            expanded.extend(children)
        else:
            expanded.append((raw_tool, args, call_id))
    if len(expanded) > MAX_NATIVE_CALLS_PER_TURN:
        return [], "expanded batch exceeds the turn call limit"
    return expanded, ""


def _plan_from_tool_objects(
    items: list[tuple[str, dict[str, Any], str]],
    *,
    policy: Any,
    controller_allowed: set[str] | None,
    snapshot_names: tuple[str, ...] | None = None,
    frozen_specs: dict[str, Any] | None = None,
) -> ToolPlan:
    items, batch_error = _lower_text_batches(items)
    if batch_error:
        return _invalid_plan(batch_error)
    if sum(1 for raw_tool, _args, _call_id in items if _canonical_name(raw_tool) == "shell") and len(items) != 1:
        return _invalid_plan("shell must be the only tool call in a turn", kind="mixed_shell_batch", tool="shell")
    if len(items) != 1 and any(_canonical_name(name) in {"submit_research_review", "submit_research_answer"} for name, _, _ in items):
        return _invalid_plan("research submission must be the only tool call in a turn")
    calls: list[ToolCall] = []
    text_keys: set[str] = set()
    for raw_tool, args, call_id in items:
        tool = _canonical_name(raw_tool)
        if not tool:
            return _invalid_plan(f"unknown tool: {raw_tool or '?'}", kind="unknown_tool", tool=(raw_tool or ""))
        if snapshot_names is not None and tool not in snapshot_names:
            return _invalid_plan(
                f"{tool} is not allowed by the current controller state (not in the turn snapshot: {tool})",
                kind="snapshot_tool_mismatch",
                tool=tool,
            )
        if tool in {"done", "ask_user"}:
            if len(items) != 1:
                return _invalid_plan(f"{tool} must be the only call in a turn", tool=tool, kind="too_many_tools")
            if not _policy_allows(policy, tool, frozen_specs):
                return _disallowed_plan(tool)
            if not _controller_allows(tool, controller_allowed):
                return _disallowed_plan(tool, controller=True)
            validated, error = _validate_tool_args(tool, args, frozen_specs=frozen_specs)
            if error:
                return _invalid_plan(error, tool=tool)
            text = str(validated.get("summary" if tool == "done" else "question") or "").strip()
            return ToolPlan(calls=[], control=Control(kind=tool, body=text), control_args=validated)
        if not _policy_allows(policy, tool, frozen_specs):
            return _disallowed_plan(tool)
        if not _controller_allows(tool, controller_allowed):
            return _disallowed_plan(tool, controller=True)
        validated, error = _validate_tool_args(tool, args, frozen_specs=frozen_specs)
        if error:
            return _invalid_plan(error, tool=tool)
        if not call_id:
            key = json.dumps([tool, validated], sort_keys=True, ensure_ascii=False)
            if key in text_keys:
                continue
            text_keys.add(key)
        calls.append(ToolCall(name=tool, args=validated, call_id=(call_id or "")))
    if not calls:
        return _invalid_plan("no JSON tool call found", kind="no_json")
    body = "Need tool result" if len(calls) == 1 else "Need tool results"
    return ToolPlan(calls=calls, control=Control(kind="continue", body=body))


def _native_tool_objects(calls: list[Any]) -> list[tuple[str, dict[str, Any], str]] | ToolPlan:
    """Unwrap native calls without losing or inventing provider call ids."""
    if len(calls) > MAX_NATIVE_CALLS_PER_TURN:
        return _invalid_plan(
            f"too many native tool calls in one turn ({len(calls)}); send at most {MAX_NATIVE_CALLS_PER_TURN}",
            kind="too_many_tools",
        )
    missing = [str(getattr(c, "name", "") or "?") for c in calls if not str(getattr(c, "id", "") or "")]
    if missing:
        return _invalid_plan(
            "native tool call without an id cannot be answered: " + ", ".join(missing),
            kind="invalid_args",
        )
    ids = [getattr(call, "id", "") for call in calls]
    if any(not isinstance(value, str) or not value.strip() or len(value) > 256 for value in ids):
        return _invalid_plan("native tool call ids must be nonempty strings of at most 256 characters", kind="invalid_args")
    if len(ids) != len(set(ids)):
        return _invalid_plan("duplicate native tool call ids cannot be answered unambiguously", kind="invalid_args")
    names = [str(getattr(c, "name", "") or "").strip().lower() for c in calls]
    if "done" in names and len(calls) != 1:
        return _invalid_plan("done must be the only call in a turn", tool="done", kind="too_many_tools")
    items = []
    for item in calls:
        name = str(getattr(item, "name", "") or "").strip().lower()
        args = getattr(item, "arguments", {})
        call_id = str(getattr(item, "id", "") or "")
        if not isinstance(args, dict):
            return _invalid_plan(f"{name} args must be an object", tool=name)
        items.append((name, dict(args), call_id))
    return items


def _decoded_text_objects(
    decoded: TextRequests | TextAnswer | TextError,
) -> list[tuple[str, dict[str, Any], str]] | ToolPlan:
    if isinstance(decoded, TextError):
        return _invalid_plan(decoded.message, tool=decoded.tool, kind=decoded.kind)
    if isinstance(decoded, TextAnswer):
        return ToolPlan(calls=[], control=Control(kind="done", body=decoded.text))
    return [(item.tool, dict(item.args), "") for item in decoded.items]


def _response_objects(reply: DecodedTextTurn | AssistantTurn) -> list[tuple[str, dict[str, Any], str]] | ToolPlan:
    if isinstance(reply, (TextRequests, TextAnswer, TextError)):
        return _decoded_text_objects(reply)
    if isinstance(reply, AssistantTurn):
        if reply.finish is TurnFinish.PROTOCOL_ERROR:
            detail = reply.raw.get("protocol_error")
            tool = reply.raw.get("protocol_tool_name")
            return _invalid_plan(detail[:500] if isinstance(detail, str) and detail else "provider returned malformed tool calls",
                                 tool=tool[:80] if isinstance(tool, str) else "", kind="invalid_args")
        if reply.finish is not TurnFinish.COMPLETE:
            return _invalid_plan("assistant response was truncated", kind="output_limit")
        if not reply.tool_calls:
            if reply.raw.get("text_protocol") is True:
                return _decoded_text_objects(decode_text_turn(reply.text))
            if not reply.text.strip():
                return _invalid_plan("empty assistant answer", kind="empty_answer")
            return ToolPlan(calls=[], control=Control(kind="done", body=reply.text.strip()))
    tool_calls = getattr(reply, "tool_calls", None) if not isinstance(reply, str) else None
    if tool_calls:
        return _native_tool_objects(list(tool_calls))
    if isinstance(reply, str):
        return _invalid_plan(
            "raw text must be decoded by the text protocol before entering the kernel",
            kind="raw_text",
        )
    return _invalid_plan("unsupported provider reply type", kind="invalid_args")


def normalize_turn(
    reply: DecodedTextTurn | AssistantTurn,
    *,
    policy: Any = None,
    controller_allowed: tuple[str, ...] | list[str] | set[str] | None = None,
    snapshot_names: tuple[str, ...] | None = None,
    snapshot: TurnSnapshot | None = None,
) -> ToolPlan:
    frozen: dict[str, Any] | None = None
    if snapshot is not None:
        try:
            if policy is not None and policy != snapshot.policy:
                return _invalid_plan("turn policy differs from the captured authorization")
            policy = snapshot.policy
            allowed_raw = getattr(snapshot, "allowed", None)
            allowed = None if allowed_raw is None else {str(n or "").strip().lower() for n in allowed_raw}
            snapshot_names = tuple(getattr(snapshot, "tool_names", ()) or ())
            frozen = frozen_spec_map(snapshot)
        except Exception as exc:
            return _invalid_plan(f"invalid tool snapshot: {exc}")
    else:
        allowed = None if controller_allowed is None else {(n or "").strip().lower() for n in controller_allowed}
    items = _response_objects(reply)
    if isinstance(items, ToolPlan):
        if snapshot is not None and snapshot.research_scope is not None and items.control is not None and items.control.kind == "done":
            return _invalid_plan("Submit the answer with submit_research_answer under the frozen contract; global done is not allowed")
        done_spec = frozen.get("done") if frozen is not None else None
        if (items.control is not None and items.control.kind == "done" and not items.protocol_error
                and done_spec is not None and "report_sections" in done_spec.required):
            return _invalid_plan("Research completion requires done.report_sections.coverage under the frozen contract; "
                                 "plain text and summary-only reports are not accepted.", tool="done")
        return items
    return _plan_from_tool_objects(
        items, policy=policy, controller_allowed=allowed,
        snapshot_names=snapshot_names, frozen_specs=frozen,
    )


__all__ = [
    "MAX_NATIVE_CALLS_PER_TURN",
    "TurnSnapshot",
    "build_turn_snapshot",
    "controller_allowed_for_session",
    "frozen_custom_executor_map",
    "frozen_spec_map",
    "normalize_turn",
]

source_snapshot.codey/operations/task_execution.py:
"""Production tool execution for the unified kernel (operations layer).

Project tools reuse the coding guards and readers (path safety, command
policy, shell approval surface); Research tools reuse ResearchTools, the
source gateway, and the evidence ledger. Completion facts come only from
successful tool results and ledger
state, never from substring matching or model-supplied parameters.
"""

from __future__ import annotations

import contextlib
import copy
import json
from dataclasses import dataclass, replace
from pathlib import Path
from typing import TYPE_CHECKING, Any

from codey.research.ledger import ResearchLedger
from codey.research.ledger_receipts import ledger_observation, source_search_observation
from codey.runtime.core.models import ToolCall, ToolResult

if TYPE_CHECKING:
    from codey.agents.tools import AgentToolFns
    from codey.research.tools import ResearchTools


def close_research_tools(tools: Any) -> None:
    """Release an owned search session without masking the task outcome."""
    close = getattr(getattr(tools, "search", None), "close", None)
    if callable(close):
        with contextlib.suppress(Exception):
            close()


def build_research_tools(deps: Any, *, session_id: str, project: str) -> ResearchTools:
    """Build the execution resources; configuration errors propagate to entry."""
    from codey.knowledge.changes import KnowledgeChanges
    from codey.research.tools import ResearchTools

    knowledge_store = getattr(deps, "knowledge_store", None)
    search_factory = getattr(deps, "search_factory", None)
    if search_factory is None:
        from codey.research.search_factory import default_research_search_provider

        search_factory = default_research_search_provider
    search = search_factory()
    try:
        return ResearchTools(
            search=search, store=knowledge_store,
            changes=KnowledgeChanges(root=knowledge_store.root) if knowledge_store is not None else None,
            diagnostics=None, session_id=session_id, project=project,
        )
    except BaseException:
        close = getattr(search, "close", None)
        if callable(close):
            with contextlib.suppress(Exception):
                close()
        raise


def effective_project_profile(permission_profile: object) -> str:
    """Project-guard profile shared by execution and shell approval.

    The Research profile controls research context and source tools. A
    project tool still needs the coding path/command guard; TaskPolicy
    has already authorized the individual project capability. Approval
    must evaluate with exactly this profile, never a hardcoded duplicate.
    """
    return "coding_writer" if str(permission_profile or "") == "research" else str(
        permission_profile or "coding_writer")


def _tool_result(call: ToolCall, outcome: Any) -> ToolResult:
    audit = dict(getattr(outcome, "audit", {}) or {})
    # Tool implementations cannot classify a request as a runtime guard refusal.
    audit.pop("execution_disposition", None)
    if call.name == "edit":
        changed = getattr(outcome, "changed", False)
        audit["changed"] = changed if type(changed) is bool else False
    return ToolResult(
        ok=outcome.ok is True, call=call, model_text=str(outcome.model_text or ""),
        truncated=bool(getattr(outcome, "truncated", False)),
        presentation=dict(getattr(outcome, "presentation", {}) or {}),
        audit=audit,
        canonical=dict(getattr(outcome, "canonical", {}) or {}),
    )


@dataclass(frozen=True)
class ProjectPolicyCheck:
    denied: bool
    message: str = ""
    approval_required: bool = False
    reason_code: str = ""


class ExecutionDelegate:
    """Real guards + real tools behind the kernel's policy snapshot."""

    def __init__(
        self,
        *,
        session: Any = None,
        project_path: Any = None,
        tool_fns: AgentToolFns | None = None,
        research_tools: Any = None,
        permission_profile: str = "coding_writer",
        approval_available: bool = False,
        change_tracker: Any = None,
        managed_outputs: Any = None,
        session_id: str = "",
        run_id: str = "",
        frozen_specs: dict[str, Any] | None = None,
        custom_executors: dict[str, Any] | None = None,
        research_scope: Any = None,
    ) -> None:
        self.session = session
        self.project_path: Path | None = Path(str(project_path)).expanduser() if project_path else None
        if self.project_path is not None and not self.project_path.is_dir():
            self.project_path = None
        self.tool_fns: AgentToolFns | None = tool_fns
        self.research_tools = research_tools
        self.permission_profile = (permission_profile or "coding_writer")
        self.approval_available = approval_available
        self.change_tracker = change_tracker
        self.managed_outputs = managed_outputs
        self.session_id = session_id
        self.run_id = run_id
        # 本轮冻结绑定：非 None 时解析/执行不再查询实时注册表。
        self._frozen_specs = frozen_specs
        self._custom_executors = custom_executors
        self._research_scope = research_scope
        if self.tool_fns is None and self.project_path is not None:
            from codey.agents.tools import build_project_tool_fns

            self.tool_fns = build_project_tool_fns(
                state_home=managed_outputs.root.parent if managed_outputs is not None else None,
            )

    def _resolve_spec(self, name: str) -> Any:
        lowered = (name or "").strip().lower()
        if self._frozen_specs is not None:
            return self._frozen_specs.get(lowered)
        try:
            from codey.toolchain.tool_spec import spec_for_tool
        except Exception:
            return None
        try:
            return spec_for_tool(lowered)
        except Exception:
            return None

    def _resolve_custom_executor(self, name: str) -> Any:
        lowered = (name or "").strip().lower()
        if self._custom_executors is not None:
            return self._custom_executors.get(lowered)
        try:
            from codey.toolchain.tool_spec import custom_executor_for
        except Exception:
            return None
        try:
            return custom_executor_for(lowered)
        except Exception:
            return None

    def handles(self, name: str) -> bool:
        spec = self._resolve_spec(name)
        if spec is None:
            return False
        if spec.executor == "receipt":
            return bool(self.session is not None)
        if spec.executor == "project":
            return self.project_path is not None and self.tool_fns is not None
        if spec.executor in {"source", "knowledge"}:
            return bool(self.research_tools is not None)
        try:
            if self._resolve_custom_executor(name or "") is not None:
                return True
        except Exception:
            pass
        return False

    def execute(self, call: ToolCall, *, turn: int = 0,
                tool_index: int = 0) -> tuple[ToolResult, bool, int | None]:
        name = (call.name or "").strip().lower()
        try:
            spec = self._resolve_spec(name)
            executor = spec.executor if spec is not None else ""
        except Exception:
            executor = ""
        if executor == "receipt":
            from codey.operations.tool_result_reader import read_tool_result

            result = read_tool_result(self, call)
            return result, result.ok, None
        if executor == "project":
            return self._execute_project(call)
        if executor in {"source", "knowledge"}:
            if not self._reserve_research_acquisition(name, turn, tool_index):
                return ToolResult(ok=False, call=call, model_text="ERROR: research acquisition budget exhausted"), False, None
            return self._execute_research(call, turn=turn, tool_index=tool_index)
        # Third-task tools run via the frozen turn binding when present,
        # otherwise the live registry.
        try:
            fn = self._resolve_custom_executor(name)
        except Exception:
            fn = None
        if callable(fn):
            try:
                produced = fn(call)
            except Exception as exc:
                result = ToolResult(ok=False, call=call, model_text=f"ERROR: {exc or 'tool failed'}")
                return result, False, None
            if not isinstance(produced, ToolResult):
                result = ToolResult(ok=False, call=call, model_text="ERROR: executor must return a structured ToolResult")
                return result, False, None
            return produced, produced.ok, None
        result = ToolResult(ok=False, call=call, model_text=f"ERROR: no production executor for {name or '?'}")
        return result, False, None

    def _policy_check(self, call: ToolCall) -> ProjectPolicyCheck:
        """Keep machine-readable denial separate from its explanation."""

        spec = self._resolve_spec(call.name)
        if spec is None:
            return ProjectPolicyCheck(True, "tool definition unavailable", False)
        if self.session is None:
            return ProjectPolicyCheck(True, "task session unavailable", False)
        if not self.session.policy.allows(spec.grant):
            return ProjectPolicyCheck(True, f"task policy denied {call.name}", False)
        if spec.executor != "project":
            return ProjectPolicyCheck(False, "", False)
        if self.project_path is None:
            return ProjectPolicyCheck(True, "no associated project", False)
        try:
            from codey.agents.tool_execution import (
                evaluate_tool_call_policy_for,
                policy_asks_user,
                policy_denied,
            )
        except Exception as exc:
            return ProjectPolicyCheck(True, f"policy unavailable: {exc}", False)
        try:
            runtime_name = {"list_dir": "ls", "read_file": "read", "grep": "search",
                            "find_references": "references"}.get(call.name, call.name)
            decision, _replay = evaluate_tool_call_policy_for(
                ToolCall(runtime_name, dict(call.args or {}), call_id=call.call_id),
                project=self.project_path,
                permission_profile=self._project_permission_profile(),
                approval_available=self.approval_available,
                phase="writer",
                shell=self.session.shell,
            )
        except Exception as exc:
            return ProjectPolicyCheck(True, f"policy error: {exc}", False)
        if decision is not None and policy_denied(decision):
            reason = str(getattr(decision, "reason", "") or getattr(decision, "reason_code", "") or "denied")
            display = decision.display
            if reason == "command_not_allowed" and not self.session.policy.allows("shell.approval"):
                display = ("This task mode cannot request shell approval. Use an interactive coding task "
                           "with command approvals enabled, or use an allowed verification command.")
            elif reason == "command_not_allowed":
                display += " Submit this command on its own in an interactive task to request approval."
            return ProjectPolicyCheck(True, f"project guard denied {call.name}: {reason}; {display}", False, reason)
        try:
            if (call.name or "") == "shell" and policy_asks_user(decision):
                return ProjectPolicyCheck(True, "shell requires user approval", True)
        except Exception:
            pass
        return ProjectPolicyCheck(False, "", False)


    def _project_permission_profile(self) -> str:
        return effective_project_profile(self.permission_profile)

    def _execute_project(self, call: ToolCall) -> tuple[ToolResult, bool, int | None]:
        if self.project_path is None:
            return ToolResult(ok=False, call=call, model_text="ERROR: project path unavailable"), False, None
        if self.tool_fns is None:
            return ToolResult(ok=False, call=call, model_text="ERROR: project tools unavailable"), False, None
        project_path = self.project_path
        check = self._policy_check(call)
        if check.denied:
            from codey.operations.kernel_result import policy_denial_result

            result = policy_denial_result(call, check.message, reason_code=check.reason_code)
            return result, False, None
        name = (call.name or "").strip().lower()
        runtime_name = {"list_dir": "ls", "read_file": "read", "grep": "search",
                        "find_references": "references"}.get(name, name)
        try:
            if runtime_name in {"ls", "read", "search", "references"}:
                from codey.agents.tool_execution import execute_information_tool_call

                outcome = execute_information_tool_call(
                    project_path, self.tool_fns,
                    ToolCall(runtime_name, dict(call.args or {})),
                )
                result = _tool_result(call, outcome)
                ok = outcome.ok if type(getattr(outcome, "ok", None)) is bool else False
                return result, ok, None
            if name == "edit":
                outcome = self._execute_edit(call)
                result = _tool_result(call, outcome)
                ok = outcome.ok if type(getattr(outcome, "ok", None)) is bool else False
                return result, ok, None
            if name == "run":
                from dataclasses import replace

                from codey.toolchain.command_output import output_tail, tail_lines

                tail = tail_lines((call.args or {}).get("output_tail_lines"))
                outcome = self.tool_fns.execute_run_command(
                    project_path, str((call.args or {}).get("path", ".") or "."),
                    str((call.args or {}).get("command", "") or ""),
                    permission_profile=self._project_permission_profile(), phase="writer",
                    tool_id=str(getattr(call, "call_id", "") or ""),
                )
                if tail is not None:
                    outcome = replace(outcome, model_text=f"Exit code: {outcome.exit_code}\n" + output_tail(outcome.model_text, tail),
                                      presentation={**outcome.presentation, "output_tail_lines": tail})
                result = _tool_result(call, outcome)
                ok = outcome.ok if type(getattr(outcome, "ok", None)) is bool else False
                return result, ok, getattr(outcome, "exit_code", None)
        except Exception as exc:
            result = ToolResult(ok=False, call=call, model_text=f"ERROR: {exc}")
            return result, False, None
        result = ToolResult(ok=False, call=call, model_text=f"ERROR: unsupported project tool {name}")
        return result, False, None

    def _execute_edit(self, call: ToolCall) -> Any:
        from codey.agents.protocol import canonical_project_path
        from codey.agents.tool_execution import read_before_edit_outcome
        from codey.toolchain.runtime import EditBlock, ToolOutcome, safe_join

        if self.project_path is None:
            return ToolOutcome.error("project path unavailable")
        if self.tool_fns is None:
            return ToolOutcome.error("project tools unavailable")
        project_path = self.project_path
        args = dict(call.args or {})
        path = str(args.get("path", "") or "")
        try:
            canonical = canonical_project_path(project_path, path)
            safe_join(project_path, canonical)
        except ValueError:
            return ToolOutcome.error("workspace_escape: path escapes project root")
        if "content" in args:
            from codey.operations.edit_base import content_edit_version

            version = content_edit_version(self.session, project_path, canonical, args)
            if self.change_tracker is not None:
                self.change_tracker.capture_before(path)
            content = str(args.get("content") or "")
            if version is None:
                outcome = self.tool_fns.write_file(project_path, path, content)
            else:
                outcome = self.tool_fns.write_file(project_path, path, content, expected_version=version)
            if outcome.ok and outcome.changed and self.change_tracker is not None:
                self.change_tracker.capture_after(path)
            return outcome
        guard = read_before_edit_outcome(
            project_path, path, set(getattr(self.session, "read_files", set()) or set()),
        )
        if guard is not None:
            return guard
        # Canonical protocol only: replacements with old_string/new_string.
        # Top-level aliases are rejected before any file write.
        for legacy in ("search", "replace"):
            if legacy in args:
                return ToolOutcome.error(f"edit rejects legacy alias: {legacy}")
        replacements = args.get("replacements")
        if not isinstance(replacements, list) or not replacements:
            return ToolOutcome.error("edit needs content or exact replacements")
        blocks: list[dict[str, str]] = []
        for item in replacements:
            if not isinstance(item, dict):
                return ToolOutcome.error("edit replacement must be a mapping")
            if set(item) != {"old_string", "new_string"}:
                return ToolOutcome.error("edit replacement must be exactly old_string/new_string")
            search = str(item.get("old_string") or "")
            replace = str(item.get("new_string") or "")
            if not search:
                return ToolOutcome.error("edit replacement search must be non-empty")
            blocks.append({"old_string": search, "new_string": replace})
        if not blocks:
            return ToolOutcome.error("edit needs content or exact replacements")
        edit_blocks = [EditBlock(old_string=b["old_string"], new_string=b["new_string"]) for b in blocks]
        if self.change_tracker is not None:
            self.change_tracker.capture_before(path)
        outcome = self.tool_fns.edit_file(self.project_path, path, edit_blocks)
        if outcome.ok and outcome.changed and self.change_tracker is not None:
            self.change_tracker.capture_after(path)
        return outcome

    def _opened_result(self, call: ToolCall, opened: Any, url: str, *, ledger: ResearchLedger, turn: int,
                       tool_index: int) -> tuple[ToolResult, bool, int | None]:
        model_text = opened.model_text
        if not opened.ok:
            return ToolResult(ok=False, call=call, model_text=model_text), False, None
        if not isinstance(ledger, ResearchLedger):
            raise ValueError("successful source read requires a research ledger observation")
        observation = opened.read_observation or ledger_observation(ledger, "open", url=url)
        from codey.research.output_receipts import maybe_externalize_output

        title = next((line.removeprefix("Title: ") for line in model_text.splitlines()
                      if line.startswith("Title: ")), "")
        outcome = maybe_externalize_output(
            store=self.managed_outputs, session_id=self.session_id, run_id=self.run_id,
            permission_profile=self.permission_profile, call=call,
            output=opened.receipt_text or model_text, ok=opened.ok,
            turn=turn, tool_index=tool_index, presentation_result=title,
            model_text_override=model_text,
        )
        base = _tool_result(call, outcome)
        merged = dict(base.canonical)
        merged["research_observation"] = observation
        if opened.read_passages:
            merged["read_passages"] = list(opened.read_passages)
        result = ToolResult(
            ok=base.ok, call=base.call, model_text=base.model_text, truncated=base.truncated,
            presentation=dict(base.presentation) if isinstance(base.presentation, dict) else {},
            audit=dict(base.audit) if isinstance(base.audit, dict) else {},
            canonical=merged,
        )
        return result, True, None

    def _observation_tools(self, *, source_read: bool = False) -> Any:
        # Acquisition mutates a temporary ledger. Only the committed result
        # receipt may publish it into the run's formal projection.
        tools = copy.copy(self.research_tools)
        from codey.research.answer_contract import AnswerScope

        if hasattr(tools, "coherent_passages"):
            tools.coherent_passages = isinstance(self._research_scope, AnswerScope)
        if hasattr(tools, "evidence_only"):
            # This is a per-call presentation setting. The shared facade and
            # stored knowledge must not inherit a child phase's output contract.
            tools.evidence_only = self.session is not None and self.session.task_kind == "evidence_followup"
        if hasattr(tools, "finding_report"):
            tools.finding_report = (self.session is not None and self.session.task_kind == "research"
                                           and self.session.policy.strict_research)
        if hasattr(tools, "local_submission"):
            # Presentation follows the admitted request, including replay. Do
            # not infer a new contract from the mutable current plan here.
            tools.local_submission = self._research_scope is not None
        ledger = getattr(tools, "ledger", None)
        if isinstance(ledger, ResearchLedger):
            # A read receipt contains this acquisition alone, not stale pages
            # inherited from the pre-call projection. Other tools need context.
            with self.session.projection_lock if self.session is not None else contextlib.nullcontext():
                tools.ledger = ResearchLedger() if source_read else ledger.clone()
            if hasattr(tools, "sources_read"):
                tools.sources_read = {url for source in ledger.opened_sources
                                      for url in (source.requested_url, source.final_url)}
            if hasattr(tools, "search_result_urls"):
                tools.search_result_urls = {hit.url for search in ledger.searches for hit in search.results}
        return tools

    def _reserve_research_acquisition(self, name: str, turn: int, tool_index: int) -> bool:
        if self.session is not None and self.session.research_acquisition_limits is not None:
            category = "search" if name == "web_search" else "open" if name in {
                "open_url", "open_result", "reopen_source", "open_hit"} else ""
            if category:
                with self.session.projection_lock:
                    slots = self.session.research_acquisition_slots
                    limit = self.session.research_acquisition_limits[0 if category == "search" else 1]
                    # Rebuilt from receipts on restore, plus in-flight slots.
                    # Failed acquisitions consume budget too.
                    previous = {key for key, kind in slots.items() if kind == category}
                    if (turn, tool_index) not in previous and len(previous) >= limit:
                        return False
                    slots[(turn, tool_index)] = category
        return True

    def _research_call_denial(self, call: ToolCall) -> tuple[ToolResult, bool, int | None] | None:
        from codey.operations.kernel_result import policy_denial_result
        from codey.research.local_scope import ResearchScope, current_scope, validate_scope_call
        from codey.research.questions import QUESTION_BOUND_TOOLS, question_ref, requires_question_ref

        try:
            if self._research_scope is not None:
                from codey.research.answer_contract import AnswerScope, digest

                scope = self._research_scope
                if isinstance(scope, AnswerScope):
                    if scope.task_digest != digest(self.session.task_text):
                        raise ValueError("research scope belongs to another task")
                else:
                    actual = current_scope(self.session, repair=scope if scope.replaces else None)
                    if not isinstance(actual, ResearchScope) or (actual.plan_digest, actual.unit_ref, actual.replaces) != (scope.plan_digest, scope.unit_ref, scope.replaces):
                        raise ValueError("research scope is stale")
                    validate_scope_call(scope, call.name, call.args)
            if call.name in QUESTION_BOUND_TOOLS:
                question_ref(call.args, self.research_tools.ledger, required=requires_question_ref(self.session))
        except ValueError as exc:
            return policy_denial_result(call, str(exc), reason_code="research_question_required"), False, None
        return None

    def _execute_research(self, call: ToolCall, *, turn: int = 0,
                          tool_index: int = 0) -> tuple[ToolResult, bool, int | None]:
        name = (call.name or "").strip().lower()
        if name == "prepare_knowledge_revision":
            from codey.research.revision_tools import preparation_result

            result = preparation_result(self.session, self._research_scope, call)
            return result, result.ok, None
        return self._execute_research_action(call, turn=turn, tool_index=tool_index)

    def _execute_research_action(self, call: ToolCall, *, turn: int = 0,
                                 tool_index: int = 0) -> tuple[ToolResult, bool, int | None]:
        name = (call.name or "").strip().lower()
        tools = self._observation_tools(source_read=name in {"open_url", "open_result", "reopen_source", "open_hit"})
        args = dict(call.args or {})
        try:
            denied = self._research_call_denial(call)
            if denied is not None:
                return denied
            if name == "research_plan":
                return self._record_research_plan(call, tools)
            if name == "submit_research_answer":
                return self._submit_research_answer(call, tools)
            if name == "web_search":
                from codey.research.text_args import first_text_arg

                outcome = tools.web_search(first_text_arg(args, "query"))
                canonical = {}
                ledger = getattr(tools, "ledger", None)
                if outcome.ok:
                    if not isinstance(ledger, ResearchLedger):
                        raise ValueError("successful search requires a research ledger observation")
                    canonical["research_observation"] = ledger_observation(ledger, name)
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text, canonical=canonical), outcome.ok, None
            if name == "open_url":
                opened = tools.open_url(str(args.get("url") or ""), offset=args.get("offset", 0),
                                        limit=args.get("limit", 6000), pages=str(args.get("pages") or ""))
                return self._opened_result(call, opened, str(args.get("url") or ""), ledger=tools.ledger,
                                           turn=turn, tool_index=tool_index)
            if name in {"open_result", "reopen_source", "open_hit"}:
                url = self._resolve_alias_url(name, args)
                if not url:
                    field, available = {
                        "open_result": ("result_id", self.session.search_results),
                        "reopen_source": ("source_id", self.session.source_ids),
                        "open_hit": ("hit_id", self.session.hit_targets),
                    }[name]
                    detail = (f"ERROR: unknown {name} id. Use {field} from these observed ids: "
                              + ", ".join(list(available)[-12:])
                              + ". A tool result_ref or out_ artifact handle is not a source locator.")
                    return ToolResult(ok=False, call=call, model_text=detail), False, None
                target = (getattr(self.session, "hit_targets", {}) or {}).get(
                    str(args.get("hit_id") or "").lower(), {}
                ) if name == "open_hit" else dict[str, Any]()
                opened = (tools.open_url(url, offset=target.get("offset", 0),
                                         pages=target.get("pages", ""))
                          if target else tools.open_url(url))
                return self._opened_result(call, opened, url, ledger=tools.ledger, turn=turn, tool_index=tool_index)
            if name == "source_search":
                query = str(args.get("query") or "")
                url = str(args.get("url") or "")
                if not url and str(args.get("source_id") or ""):
                    url = self._resolve_alias_url("reopen_source", {"source_id": args.get("source_id")}) or ""
                outcome = tools.source_search(url, query, args.get("limit", 6))
                if outcome.ok:
                    ledger = getattr(tools, "ledger", None)
                    if not isinstance(ledger, ResearchLedger):
                        raise ValueError("successful source search requires a research ledger observation")
                    observation = ledger_observation(ledger, name)
                    text, mapping = self._build_hit_mapping(source_search_observation(observation))
                    hit_canonical: dict[str, object] = {"hit_targets": mapping, "research_observation": observation}
                    return (
                        ToolResult(ok=outcome.ok, call=call, model_text=text, canonical=hit_canonical),
                        True, None,
                    )
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text), outcome.ok, None
            if name == "knowledge_search":
                from codey.research.text_args import first_text_arg

                outcome = tools.knowledge_search(first_text_arg(args, "query"), depth=args.get("depth", 1))
                search_canonical = ({"knowledge_search_empty": True}
                    if outcome.ok and getattr(outcome, "knowledge_search_empty", False) is True else {})
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text,
                                  canonical=search_canonical), outcome.ok, None
            if name == "knowledge_read":
                return self._read_research_knowledge(call, tools)
            if name == "knowledge_commit":
                return self._commit_research_knowledge(call, tools)
            if name in {"knowledge_write", "save_finding", "save_inference"}:
                return self._execute_research_write(call, tools)
            if name == "knowledge_link":
                links_before = tools.links_created
                outcome = tools.knowledge_link(str(args.get("src") or ""), str(args.get("dst") or ""),
                                            str(args.get("kind") or "relates"))
                return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text,
                    canonical={"knowledge_links_created": tools.links_created - links_before}), outcome.ok, None
        except Exception as exc:
            return ToolResult(ok=False, call=call, model_text=f"ERROR: {exc}"), False, None
        return ToolResult(ok=False, call=call, model_text=f"ERROR: unknown research tool {name}"), False, None

    def _commit_research_knowledge(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.research.answer_contract import AnswerScope

        if isinstance(self._research_scope, AnswerScope) and any(
            row.get("value", {}).get("kind") not in {"claim", "inference", "question", "entity", "observation"}
            for row in call.args.get("changes", [])
        ):
            raise ValueError("whole research knowledge_commit only accumulates explicit claims, inferences, "
                             "questions, entities or observations; answer publication owns source/evidence/answer")
        outcome = tools.knowledge_commit(call.args)
        return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text), outcome.ok, None

    def _read_research_knowledge(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.research.answer_contract import AnswerScope
        from codey.research.questions import question_ref

        args = call.args
        identity = str(args.get("id") or "")
        outcome = tools.knowledge_read(identity, revision=args.get("revision"), question_ref=question_ref(args, tools.ledger),
                                       offset=args.get("offset", 0), limit=args.get("limit", 6000),
                                       whole_answer=isinstance(self._research_scope, AnswerScope))
        text = outcome.model_text
        if not outcome.ok and self._research_scope is not None:
            if identity in tools.ledger.read_passages:
                text = ("ERROR: this id names a read passage, not a stored knowledge object. "
                        "Use its complete text if present in read_evidence; otherwise recover its original read with "
                        "read_tool_result using read_receipt_index. Choose an answer or a gap from the actual evidence.")
            elif identity in getattr(self.session, "source_ids", {}):
                text = ("ERROR: this id is an opened-source locator, not a stored knowledge object. "
                        "Recover its original read with read_tool_result using read_receipt_index, or use an advertised "
                        "source-reading action for more text. knowledge_read needs an exact stored id and revision.")
        canonical: dict[str, Any] = {
            "research_reference_bindings": {k: v.to_dict() for k, v in tools.ledger.references.items()}} if outcome.ok else {}
        if outcome.ok and outcome.read_passages:
            canonical.update(research_observation=outcome.read_observation, read_passages=list(outcome.read_passages))
        return ToolResult(ok=outcome.ok, call=call, model_text=text, canonical=canonical), outcome.ok, None

    def _record_research_plan(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.research.plan_contract import frozen_plan_version, is_compact_plan_spec

        spec = self._frozen_specs.get(call.name) if self._frozen_specs is not None else None
        compact = is_compact_plan_spec(spec)
        version = frozen_plan_version(spec) if compact else 1
        args = call.args
        if compact and args.get("contract_version", version) != version:
            raise ValueError("contract_version must match the frozen entry")
        outcome = tools.research_plan(args.get("questions"), question_details=args.get("question_details"),
                                      task=str(getattr(self.session, "task_text", "")), schema_version=version)
        canonical = {"research_observation": outcome.read_observation} if outcome.ok else {}
        return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text, canonical=canonical), outcome.ok, None

    def _submit_research_answer(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        from codey.knowledge.model import canonical_json
        from codey.research.answer_contract import AnswerScope, submit_answer
        from codey.research.local_scope import selection_budget, submission, submission_finding

        if isinstance(self._research_scope, AnswerScope):
            declared = submit_answer(self._research_scope, call.args)
            return ToolResult(call, "Whole answer recorded. The application will validate and publish this submission.",
                              ok=True, canonical={"research_submission": declared}), True, None

        canonical: dict[str, Any] = {}
        created_finding = None
        if self._research_scope is None:
            raise ValueError("submit_research_answer requires an original frozen research scope")
        finding = submission_finding(self._research_scope, call.args)
        if finding is not None:
            saved, ok, code = self._execute_research_write(ToolCall("save_finding", finding), tools)
            if not ok:
                if "version literal absent from selected original excerpts:" in saved.model_text:
                    from codey.research.source_literals import version_anchors

                    available = [(ref, tools.ledger.read_passages[ref].excerpt) for ref in self._research_scope.passage_refs]
                    saved = replace(saved, model_text=saved.model_text + "\n" + canonical_json({
                        "available_version_locators": version_anchors(finding["claim"], available),
                        "next": "Full windows are in read_evidence. Select one primary passage_ref and up to 3 OTHER "
                                "additional_passage_refs from the same exact source version to support the whole answer. "
                                "These number matches are locators, not semantic approval or automatic adoption."}))
                return replace(saved, call=call), False, code
            saved_ref = json.loads(saved.model_text)["finding_ref"]
            binding = tools.ledger.references[saved_ref]
            created_finding = (saved_ref, binding.object_id, binding.revision)
            canonical.update(saved.canonical)
        answer = submission(self.session, tools.ledger, self._research_scope, call.args, created_finding=created_finding)
        canonical["research_answer"] = answer
        return ToolResult(ok=True, call=call, model_text=canonical_json({
            "unit_ref": answer["unit_ref"], "state": answer["state"], "selection_recorded": True,
            **({"finding_ref": created_finding[0], "interpretation_review": "unreviewed"} if created_finding else {}),
            "report_budget": selection_budget(self.session, tools.ledger, tools.store, pending_answer=answer),
            "next": "The kernel advances the original plan or checks its parent report. No global done is needed."}),
            canonical=canonical), True, None

    def _execute_research_write(self, call: ToolCall, tools: Any) -> tuple[ToolResult, bool, int | None]:
        name, args = call.name, dict(call.args or {})
        before = len(getattr(getattr(tools, "ledger", None), "evidence_items", ()) or ())
        created_before, updated_before = set(tools.created_ids), set(tools.updated_ids)
        links_before = tools.links_created
        lowered, problem = (self._lower_finding_source(args) if name == "save_finding" else
                            (args, "") if name == "save_inference" else self._lower_knowledge_sources(args))
        if problem:
            return ToolResult(ok=False, call=call, model_text=f"ERROR: {problem}"), False, None
        outcome = (tools.save_finding(lowered) if name == "save_finding" else
                   tools.save_inference(lowered) if name == "save_inference" else tools.knowledge_write(lowered))
        if not outcome.ok:
            return ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text), False, None
        evidence = self._ledger_evidence(before, tools.ledger)
        evidence_canonical: dict[str, object] = {"evidence_items": evidence}
        if name in {"save_finding", "save_inference"}:
            evidence_canonical["research_reference_bindings"] = {k: v.to_dict() for k, v in tools.ledger.references.items()}
        evidence_canonical["knowledge_links_created"] = tools.links_created - links_before
        proposals: list[object] = []
        created = [item for item in tools.created_ids if item not in created_before]
        target = str(lowered.get("id") or "")
        updated = list(dict.fromkeys([item for item in tools.updated_ids if item not in updated_before] +
            ([target] if target in tools.updated_ids else [])))
        evidence_canonical["knowledge_notes"] = {
            "created": created,
            "updated": updated,
            "proposals": proposals,
        }
        affected = list(dict.fromkeys([*created, *updated]))
        self._staged_note_receipt(tools, affected, proposals, evidence_canonical)
        ledger = getattr(tools, "ledger", None)
        if isinstance(ledger, ResearchLedger) and name != "save_inference":
            evidence_canonical["research_observation"] = ledger_observation(ledger, name, evidence_start=before)
        return (
            ToolResult(ok=outcome.ok, call=call, model_text=outcome.model_text, canonical=evidence_canonical),
            True, None,
        )

    @staticmethod
    def _staged_note_receipt(tools: Any, created: list[str], proposals: list[object], canonical: dict[str, object]) -> None:
        from codey.providers.response_record import json_value
        from codey.research.staging import StagedKnowledgeStore

        if isinstance(getattr(tools, "store", None), StagedKnowledgeStore):
            proposals.extend(json_value(tools.store._staged_notes[identity]) for identity in created)
            canonical["knowledge_bases"] = {identity: tools.store._staged_bases[identity] for identity in created}
            canonical["knowledge_batches"] = {
                identity: {"commit_id": batch[0], "mutations": [
                    {"value": mutation.value.to_dict(), "expected_revision": mutation.expected_revision}
                    for mutation in batch[1]]}
                for identity, batch in tools.store._staged_knowledge.items() if identity in created
            }

    def _lower_knowledge_sources(self, args: dict[str, Any]) -> tuple[dict[str, Any], str]:
        import re

        sources = dict(getattr(self.session, "source_ids", {}) or {})

        def lower(value: object) -> tuple[str, str]:
            text = str(value or "").strip()
            key = text.lower()
            if key in sources:
                return str(sources[key]), ""
            if re.fullmatch(r"s[1-9][0-9]*", key):
                return "", f"unknown source_id: {text}"
            return text, ""

        lowered = dict(args)
        if isinstance(args.get("sources"), list):
            rows: list[str] = []
            for value in args["sources"]:
                resolved, error = lower(value)
                if error:
                    return {}, error
                rows.append(resolved)
            lowered["sources"] = rows
        if isinstance(args.get("evidence"), list):
            evidence: list[dict[str, Any]] = []
            for value in args["evidence"]:
                if not isinstance(value, dict):
                    evidence.append(value)
                    continue
                row = dict(value)
                for key in ("source_url", "source"):
                    if key in row:
                        resolved, error = lower(row[key])
                        if error:
                            return {}, error
                        row[key] = resolved
                evidence.append(row)
            lowered["evidence"] = evidence
        return lowered, ""

    def _lower_finding_source(self, args: dict[str, Any]) -> tuple[dict[str, Any], str]:
        # The selected passage owns the source identity. An explicitly supplied
        # source is only an assertion to validate, including frozen older calls.
        if "source_ref" not in args:
            return args, ""
        reference = args.get("source_ref")
        sources = dict(getattr(self.session, "source_ids", {}) or {})
        if not isinstance(reference, str) or reference not in sources:
            return {}, "source_ref must be an exact opened source reference: " + ", ".join(sources)
        return {**args, "source_ref": sources[reference]}, ""

    def _resolve_alias_url(self, alias: str, args: dict[str, Any]) -> str:
        session = self.session
        key = {"open_result": "result_id", "reopen_source": "source_id", "open_hit": "hit_id"}.get(alias, "")
        rid = str(args.get(key, "") or "").strip().lower() if key else ""
        if not rid or session is None:
            return ""
        results = dict(getattr(session, "search_results", {}) or {})
        sources = dict(getattr(session, "source_ids", {}) or {})
        if alias == "open_hit":
            return str((getattr(session, "hit_targets", {}) or {}).get(rid, {}).get("url", "") or "")
        return str(results.get(rid, "") or sources.get(rid, "") or "")

    def _build_hit_mapping(self, observation: dict[str, Any]) -> tuple[str, dict[str, dict[str, object]]]:
        """Build hit text plus its mapping without touching the session.

        IDs consider both the live session mapping and the current batch so
        repeated IDs never collide. The caller persists the mapping in the
        receipt canonical; the single fact entry applies it to the session.
        """
        from codey.research.source_search import SourceSearchHit, render_results

        existing = dict(getattr(self.session, "hit_targets", {}) or {}) if self.session is not None else {}
        batch: dict[str, dict[str, object]] = {}
        by_target: dict[tuple[str, int, str], str] = {}
        for key, value in list(existing.items()):
            if isinstance(value, dict):
                by_target[(str(value.get("url", "")), int(value.get("offset", 0) or 0), str(value.get("pages", "")))] = key
        hit_ids = []
        counter = len(existing) + 1
        for hit in observation["hits"]:
            page = hit["page"]
            target = (observation["source_url"], 0 if page is not None else hit["offset"],
                      str(page) if page is not None else "")
            hit_id = by_target.get(target, "")
            if not hit_id:
                while f"h{counter}" in existing or f"h{counter}" in batch:
                    counter += 1
                hit_id = f"h{counter}"
                counter += 1
                by_target[target] = hit_id
            # The receipt describes this query's targets, including reused ids.
            # Otherwise the display cannot distinguish an empty result from a
            # repeat query that legitimately found the same passages.
            batch[hit_id] = {"url": target[0], "offset": target[1], "pages": target[2]}
            hit_ids.append(hit_id)
        hits = [SourceSearchHit(**hit) for hit in observation["hits"]]
        return render_results(hits, hit_ids=tuple(hit_ids)), batch

    def _ledger_evidence(self, before: int, ledger: ResearchLedger) -> list[dict[str, str]]:
        items = list(getattr(ledger, "evidence_items", ()) or [])
        fresh = items[before:] if before >= 0 else items
        evidence: list[dict[str, str]] = []
        for item in fresh:
            url = str(getattr(item, "source_url", "") or "").strip()
            excerpt = str(getattr(item, "excerpt", "") or "").strip()
            if url and excerpt:
                evidence.append({"source_url": url, "excerpt": excerpt[:600]})
        return evidence


__all__ = ["ExecutionDelegate", "build_research_tools", "close_research_tools"]

